import{_ as e,o as n,c as s,a6 as l}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"Codex 中文手册","description":"基于 Codex CLI v0.167.0 官方文档整理的 Codex 中文手册。","frontmatter":{"title":"Codex 中文手册","description":"基于 Codex CLI v0.167.0 官方文档整理的 Codex 中文手册。","source":"https://daiw.org/manual/codex"},"headers":[],"relativePath":"manual/agent/codex/index.md","filePath":"manual/agent/codex/index.md"}'),t={name:"manual/agent/codex/index.md"};function i(o,a,d,r,c,p){return n(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="codex-中文手册" tabindex="-1">Codex 中文手册 <a class="header-anchor" href="#codex-中文手册" aria-label="Permalink to &quot;Codex 中文手册&quot;">​</a></h1><blockquote><p>内容来源：<a href="https://daiw.org/manual/codex" target="_blank" rel="noreferrer">daiw.org</a> · 作者 David · 原文更新于 2026-11-06</p></blockquote><blockquote><p>基于 Codex CLI v0.167.0 官方文档整理的 Codex 中文手册。</p></blockquote><p><a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">Codex CLI</a> 是 OpenAI 出品、在你本机运行的编码 agent，以 <code>codex</code> 命令启动：在终端里阅读代码、修改文件、执行命令、调用 MCP 工具，也能用 <code>codex exec</code> 嵌入脚本和 CI 流水线。它用 Rust 编写，以 Apache-2.0 协议在 GitHub 开源（仓库 <code>openai/codex</code>）。</p><p>本手册已核对至 <strong>Codex CLI v0.167.0</strong>（GitHub tag <code>rust-v0.167.0</code>，2026-11-06 发布），依据官方文档与近期稳定版发布说明整理。Codex 迭代很快，具体行为请以你本机的版本为准：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 检查安装、配置、登录与运行环境</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="codex-的几种形态" tabindex="-1">Codex 的几种形态 <a class="header-anchor" href="#codex-的几种形态" aria-label="Permalink to &quot;Codex 的几种形态&quot;">​</a></h2><p>同一个 Codex 有多个使用入口。本手册以 CLI 为主，其他形态只在相关处简要提及：</p><table tabindex="0"><thead><tr><th>形态</th><th>运行位置</th><th>与 CLI 的关系</th></tr></thead><tbody><tr><td>Codex CLI</td><td>本机终端</td><td>本手册的主题，开源</td></tr><tr><td>ChatGPT 桌面应用中的 Codex</td><td>macOS、Windows（Linux 版处于预览阶段）</td><td>图形界面的本地客户端。<code>codex app</code> 可以从终端打开它（未安装时启动安装程序），会话中输入 <code>/app</code> 可把当前会话转到桌面端继续</td></tr><tr><td>IDE 扩展</td><td>VS Code、Cursor、Windsurf 等（Xcode、JetBrains 有各自的集成）</td><td>编辑器侧边栏里的 Codex，不开源</td></tr><tr><td>Codex cloud</td><td>OpenAI 托管的隔离容器</td><td>在云端并行运行任务。CLI 中用 <code>codex cloud</code> 浏览或提交云端任务，用 <code>codex apply</code> 把任务产生的 diff 应用到本地；只支持 ChatGPT 账号登录</td></tr></tbody></table><p>桌面应用、CLI 与 IDE 扩展读取同一个配置文件 <code>~/.codex/config.toml</code>；CLI 与 IDE 扩展还共享同一份登录缓存，在其中一处登出后，两边下次启动都需要重新登录。</p><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 安装（macOS / Linux；Windows 与其他方式见安装页）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://chatgpt.com/codex/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 进入项目目录启动，首次运行按提示登录（推荐 Sign in with ChatGPT）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 在会话里为项目生成 AGENTS.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/init</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. 在脚本或 CI 中非交互运行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;总结这个仓库的结构，列出风险最高的 5 个模块&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>之后的日常使用，基本就是“用自然语言描述任务，在需要时用斜杠命令调整会话”，常见套路见<a href="/Front2Full/manual/agent/codex/scenarios">常见使用场景</a>。</p><h2 id="手册导读" tabindex="-1">手册导读 <a class="header-anchor" href="#手册导读" aria-label="Permalink to &quot;手册导读&quot;">​</a></h2><p><strong>入门</strong></p><ul><li><a href="/Front2Full/manual/agent/codex/installation">安装、登录与升级</a>——系统要求，安装脚本、npm、Homebrew 与二进制安装，登录方式与凭据存储，<code>codex update</code>、<code>codex doctor</code> 与卸载。</li><li><a href="/Front2Full/manual/agent/codex/cli-flags">启动命令行选项</a>——全部子命令一览，以及模型、沙箱与审批、目录、配置覆盖等全局参数。</li><li><a href="/Front2Full/manual/agent/codex/configuration">配置文件 config.toml</a>——Codex 的主要配置入口。</li><li><a href="/Front2Full/manual/agent/codex/config-reference">配置项速查</a>——<code>config.toml</code> 配置项的速查表。</li><li><a href="/Front2Full/manual/agent/codex/environment-variables">环境变量</a>——按用途分组的环境变量，以及 Codex 注入给子进程的变量。</li><li><a href="/Front2Full/manual/agent/codex/scenarios">常见使用场景</a>——从初次运行到 CI、代码审查、MCP、本地模型的实操套路。</li></ul><p><strong>核心概念</strong></p><ul><li><a href="/Front2Full/manual/agent/codex/sandbox-approvals">沙箱、审批与安全</a>、<a href="/Front2Full/manual/agent/codex/agents-md">AGENTS.md 项目指令</a>、<a href="/Front2Full/manual/agent/codex/models">模型与推理</a>。</li></ul><p><strong>命令参考</strong></p><ul><li><a href="/Front2Full/manual/agent/codex/slash-commands">斜杠命令</a>、<a href="/Front2Full/manual/agent/codex/exec">非交互模式 codex exec</a>、<a href="/Front2Full/manual/agent/codex/sessions">会话管理</a>、<a href="/Front2Full/manual/agent/codex/review">代码审查</a>。</li></ul><p><strong>进阶</strong></p><ul><li><a href="/Front2Full/manual/agent/codex/rules">命令规则 Rules</a>、<a href="/Front2Full/manual/agent/codex/mcp">MCP 集成</a>、<a href="/Front2Full/manual/agent/codex/skills">Skills 技能</a>、<a href="/Front2Full/manual/agent/codex/plugins">插件</a>、<a href="/Front2Full/manual/agent/codex/hooks">Hooks</a>、<a href="/Front2Full/manual/agent/codex/subagents">子代理</a>、<a href="/Front2Full/manual/agent/codex/sdk-app-server">SDK 与 App Server</a>、<a href="/Front2Full/manual/agent/codex/cloud-integrations">Codex Cloud、GitHub 与 IDE</a>。</li></ul><p><strong>其它</strong></p><ul><li><a href="/Front2Full/manual/agent/codex/changelog">更新日志</a>。</li></ul><h2 id="与《claude-code-中文手册》的关系" tabindex="-1">与《Claude Code 中文手册》的关系 <a class="header-anchor" href="#与《claude-code-中文手册》的关系" aria-label="Permalink to &quot;与《Claude Code 中文手册》的关系&quot;">​</a></h2><p>本站的<a href="https://daiw.org/manual/claude-code" target="_blank" rel="noreferrer">《Claude Code 中文手册》</a>与本手册结构基本对应，两者的很多概念可以一一对照（例如 <code>AGENTS.md</code> 之于 <code>CLAUDE.md</code>、<code>codex exec</code> 之于 <code>claude -p</code>），同时使用两款工具时可以对照阅读。</p><h2 id="想看源码怎么实现" tabindex="-1">想看源码怎么实现 <a class="header-anchor" href="#想看源码怎么实现" aria-label="Permalink to &quot;想看源码怎么实现&quot;">​</a></h2><p>本手册讲怎么用。想知道这些功能在源码里是怎么实现的（app-server 协议、agent 循环、工具编排、三个平台的沙箱等），可以接着读本站的<a href="https://daiw.org/manual/codex-source" target="_blank" rel="noreferrer">《Codex 源码解读》</a>。源码解读目前以 <code>rust-v0.158.0</code> 为准，各章会链接回本手册的对应页面；CLI 后续版本的变化请以本手册与官方发布记录为准。</p>`,28)])])}const g=e(t,[["render",i]]);export{u as __pageData,g as default};
